import React, { useCallback, useEffect, useRef } from 'react';
import { useIntl } from 'react-intl';
import { Row, TableInstance } from 'react-table';
import styled from 'styled-components';

import { Checkbox } from '../../../forms/checkbox/Checkbox.js';
import { dataTableMessages } from '../../DataTable/messages.js';
import { getBatchSelectRange } from '../../utils/row-select-utils.js';

// #region StyledComponents
const StyledCheckboxContainer = styled.div({
  display: 'contents',
});
// #endregion StyledComponents

//TODO: React 18 update figure out typesafe return here.
export const createSelectableRowCheckbox = (): ((
  props: TableInstance & {
    row: Row;
    currentRowIndex: number;
  },
) => JSX.Element) => {
  let firstSelection: number | undefined = undefined;
  let lastRange: [number, number] | undefined = undefined;
  let shiftKey = false;

  return (
    props: TableInstance & {
      row: Row;
      currentRowIndex: number;
    },
  ) => {
    const {
      row,
      currentRowIndex,
      page: currentPageRows,
      state: { selectedRowIds, pageSize = 0, pageIndex },
      updateSelectedRows,
      manualPagination,
      rows,
    } = props;
    const { checked = false } = row.getToggleRowSelectedProps();

    const intl = useIntl();

    const containerRef = useRef<HTMLDivElement | null>(null);

    // The default behaviour of Browsers when holding shift and
    // clicking is to select any text and we don't want that when selecting a range
    const onSelectStart = useCallback((ev: Event) => ev.preventDefault(), []);

    const onChange = useCallback(
      (checked: boolean) => {
        if (!shiftKey || firstSelection === undefined) {
          firstSelection = currentRowIndex;
          lastRange = undefined;
          // consider pagination and sorting when getting the rowId
          // or fallback to current row index without page index offset calculation
          const paginatedRowIndex = manualPagination
            ? currentRowIndex
            : pageSize * pageIndex + currentRowIndex;

          const rowId = rows[paginatedRowIndex].id;
          const newSelectedRowIds: Record<string, boolean> = {
            ...selectedRowIds,
            [rowId]: checked,
          };
          updateSelectedRows(newSelectedRowIds);
          return;
        }

        const selected = currentPageRows[firstSelection].isSelected;

        const selectionRange =
          firstSelection < currentRowIndex
            ? ([firstSelection, currentRowIndex] as const)
            : ([currentRowIndex, firstSelection] as const);

        const [selectionStart, selectionEnd] = selectionRange;

        const unselectRange = selected ? lastRange : selectionRange;
        const selectRange = selected ? selectionRange : undefined;
        const batchSelectRange = getBatchSelectRange(
          currentPageRows,
          selectedRowIds,
          selectRange,
          unselectRange,
        );

        updateSelectedRows(batchSelectRange);

        lastRange = [selectionStart, selectionEnd];
      },
      [
        currentPageRows,
        currentRowIndex,
        pageIndex,
        pageSize,
        rows,
        selectedRowIds,
        updateSelectedRows,
      ],
    );

    const onClick = useCallback(
      (ev: MouseEvent) => {
        shiftKey = ev.shiftKey;
        // No Browser currently dispatches the change event on input elements when holding shift and clicking.
        // Except for Firefox all of them still toggle the input element.
        // see: https://bugzilla.mozilla.org/show_bug.cgi?id=559506
        // To have a consistent behaviour across all browsers we create a wrapper div.
        // On it we prevent the change event from triggering and call the `onChange` callback manually.
        ev.preventDefault();
        onChange(!row.isSelected);
      },
      [row, onChange],
    );

    useEffect(() => {
      const { current: div } = containerRef;

      if (!div) {
        return;
      }

      div.addEventListener('click', onClick, true);
      div.addEventListener('selectstart', onSelectStart);

      return () => {
        div.removeEventListener('click', onClick, true);
        div.removeEventListener('selectstart', onSelectStart);
      };
    }, [containerRef, onClick, onSelectStart]);

    return (
      <StyledCheckboxContainer ref={containerRef}>
        <Checkbox
          value={checked}
          aria-label={
            checked
              ? intl.formatMessage(dataTableMessages.deselectRow)
              : intl.formatMessage(dataTableMessages.selectRow)
          }
          onChange={() => undefined}
        />
      </StyledCheckboxContainer>
    );
  };
};
